mkdeclimpl! {
impl ExpansionInfo { pub fn expanded (& self) -> InMacroFile < SyntaxNode > { self . expanded . clone () } pub fn arg (& self) -> InFile < Option < & SyntaxNode > > { self . arg . as_ref () . map (| it | it . as_ref ()) } pub fn call_file (& self) -> HirFileId { self . arg . file_id } pub fn is_attr (& self) -> bool { matches ! (self . loc . def . kind , MacroDefKind :: BuiltInAttr (..) | MacroDefKind :: ProcMacro (_ , _ , ProcMacroKind :: Attr)) } # [doc = " Maps the passed in file range down into a macro expansion if it is the input to a macro call."] # [doc = ""] # [doc = " Note this does a linear search through the entire backing vector of the spanmap."] pub fn map_range_down_exact (& self , span : Span ,) -> Option < InMacroFile < impl Iterator < Item = (SyntaxToken , SyntaxContext) > + '_ > > { let tokens = self . exp_map . ranges_with_span_exact (span) . flat_map (move | (range , ctx) | { self . expanded . value . covering_element (range) . into_token () . zip (Some (ctx)) }) ; Some (InMacroFile :: new (self . expanded . file_id , tokens)) } # [doc = " Maps the passed in file range down into a macro expansion if it is the input to a macro call."] # [doc = " Unlike [`map_range_down_exact`], this will consider spans that contain the given span."] # [doc = ""] # [doc = " Note this does a linear search through the entire backing vector of the spanmap."] pub fn map_range_down (& self , span : Span ,) -> Option < InMacroFile < impl Iterator < Item = (SyntaxToken , SyntaxContext) > + '_ > > { let tokens = self . exp_map . ranges_with_span (span) . flat_map (move | (range , ctx) | { self . expanded . value . covering_element (range) . into_token () . zip (Some (ctx)) }) ; Some (InMacroFile :: new (self . expanded . file_id , tokens)) } # [doc = " Looks up the span at the given offset."] pub fn span_for_offset (& self , db : & dyn ExpandDatabase , offset : TextSize ,) -> (FileRange , SyntaxContext) { debug_assert ! (self . expanded . value . text_range () . contains (offset)) ; span_for_offset (db , & self . exp_map , offset) } # [doc = " Maps up the text range out of the expansion hierarchy back into the original file its from."] pub fn map_node_range_up (& self , db : & dyn ExpandDatabase , range : TextRange ,) -> Option < (FileRange , SyntaxContext) > { debug_assert ! (self . expanded . value . text_range () . contains_range (range)) ; map_node_range_up (db , & self . exp_map , range) } # [doc = " Maps up the text range out of the expansion into its macro call."] # [doc = ""] # [doc = " Note that this may return multiple ranges as we lose the precise association between input to output"] # [doc = " and as such we may consider inputs that are unrelated."] pub fn map_range_up_once (& self , db : & dyn ExpandDatabase , token : TextRange ,) -> InFile < smallvec :: SmallVec < TextRange , 1 > > { debug_assert ! (self . expanded . value . text_range () . contains_range (token)) ; let span = self . exp_map . span_at (token . start ()) ; match & self . arg_map { SpanMap :: RealSpanMap (_) => { let file_id = EditionedFileId :: from_span (db , span . anchor . file_id) . into () ; let anchor_offset = db . ast_id_map (file_id) . get_erased (span . anchor . ast_id) . text_range () . start () ; InFile { file_id , value : SmallVec :: < TextRange , 1 > :: from_vec (vec ! [span . range + anchor_offset]) , } } SpanMap :: ExpansionSpanMap (arg_map) => { let Some (arg_node) = & self . arg . value else { return InFile :: new (self . arg . file_id , smallvec :: smallvec ! []) ; } ; let arg_range = arg_node . text_range () ; InFile :: new (self . arg . file_id , arg_map . ranges_with_span_exact (span) . filter (| (range , _) | range . intersect (arg_range) . is_some ()) . map (TupleExt :: head) . collect () ,) } } } pub fn new (db : & dyn ExpandDatabase , macro_file : MacroCallId) -> ExpansionInfo { let _p = tracing :: info_span ! ("ExpansionInfo::new") . entered () ; let loc = db . lookup_intern_macro_call (macro_file) ; let arg_tt = loc . kind . arg (db) ; let arg_map = db . span_map (arg_tt . file_id) ; let (parse , exp_map) = db . parse_macro_expansion (macro_file) . value ; let expanded = InMacroFile { file_id : macro_file , value : parse . syntax_node () , } ; ExpansionInfo { expanded , loc , arg : arg_tt , exp_map , arg_map , } } }
}